class Patch {
    // 🐴 Keep the source's UTF-16 offsets and CRLF line endings.
    @Defs(value = [
        Def(id = "call", method = ["Ltarget/Target;compute()I"]),
        Def(id = "field", field = ["Ltarget/Target;value:I"]),
        Def(type = [String::class], id = "text"),
        Def(id = "local", local = [Capture(name = ["first", "second"], type = String::class)])
    ])
    @Def(id = "direct", field = ["Ltarget/Target;value:I"])
    @Expr("direct")
    @Exprs([Expr(id = "main", value = ["call()", "field"])])
    @Modify(method = ["tick"], at = [Point("MIXINEXTRAS:EXPRESSION", id = "main")])
    fun handler(value: Int): Int = value
}

